1	// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
2	// ops against the RISC-V Debug Module. The orchestration is testable in
3	// isolation by injecting a recording bus.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/resume_driver.hpp"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_regfile_xfer.hpp"
10	
11	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
12	#include <doctest.h>
13	
14	#include <cstdint>
15	#include <deque>
16	#include <optional>
17	#include <vector>
18	
19	namespace {
20	
21	// DMI register addresses from RISC-V Debug Spec 1.0.
22	constexpr uint8_t kDmcontrol  = 0x10;
23	constexpr uint8_t kDmstatus   = 0x11;
24	constexpr uint8_t kAbstractcs = 0x16;
25	constexpr uint8_t kCommand    = 0x17;
26	constexpr uint8_t kData0      = 0x04;
27	constexpr uint8_t kData1      = 0x05;
28	
29	// CSR numbers from Debug Spec.
30	constexpr uint16_t kCsrDpc = 0x7B1;
31	
32	struct DmiOp
33	{
34	  enum class Kind
35	  {
36	    Write,
37	    Read,
38	  };
39	  Kind kind;
40	  uint8_t reg;
41	  uint32_t value;  // for writes only
42	};
43	
44	struct RecordingBus final : hybrid::DmiBus
45	{
46	  std::vector<DmiOp> ops;
47	
48	  // Test-controlled response values for reads.
49	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
50	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
51	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
52	
53	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
54	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
55	  // fallback). Models real hardware and -- unlike positional queueing -- is
56	  // robust to however many unrelated abstract ops precede the targeted write.
57	  std::optional<uint16_t> fail_csr_write;
58	
59	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
60	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
61	  // re-arms to false after firing - tests can flip it back on to fail a
62	  // later PB exec.
63	  bool fail_next_pb_exec = false;
64	
65	  void write(uint8_t reg, uint32_t value) override
66	  {
67	    ops.push_back({DmiOp::Kind::Write, reg, value});
68	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
69	      cmderr_sticky_ = false;  // W1C clear
70	    if (reg == kCommand && fail_csr_write) {
71	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
72	      const bool is_write = ((value >> 16) & 1u) != 0u;
73	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
74	        cmderr_sticky_ = true;
75	    }
76	    if (reg == kCommand && value == hybrid::kExecProgbufCmd
77	        && fail_next_pb_exec) {
78	      cmderr_sticky_ = true;
79	      fail_next_pb_exec = false;
80	    }
81	  }
82	
83	  auto read(uint8_t reg) -> uint32_t override
84	  {
85	    ops.push_back({DmiOp::Kind::Read, reg, 0});
86	    if (reg == kDmstatus) return dmstatus_value;
87	    if (reg == kAbstractcs) {
88	      if (cmderr_sticky_) return kCmderrMask;
89	      if (!abstractcs_queue.empty()) {
90	        auto v = abstractcs_queue.front();
91	        abstractcs_queue.pop_front();
92	        return v;
93	      }
94	      return abstractcs_value;
95	    }
96	    return 0;
97	  }
98	
99	private:
100	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
101	  bool cmderr_sticky_ = false;
102	};
