126	auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
127	{
128	  std::size_t n = 0;
129	  for (const auto& op : ops)
130	    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
