136	TEST_CASE("resume halts the hart before any abstract command")
137	{
138	  RecordingBus bus;
139	  // dmstatus answers halted+resumeack so poll loops finish on the first read.
140	  bus.dmstatus_value = (1u << 9) | (1u << 17);
141	
142	  hybrid::ResumeDriver driver(bus);
143	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x10=*/0xdeadbeef));
144	
145	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
146	  // accepted; the second write must add haltreq while keeping dmactive set.
147	  REQUIRE(bus.ops.size() >= 2);
148	
149	  const auto& prime = bus.ops[0];
150	  CHECK(prime.kind == DmiOp::Kind::Write);
151	  CHECK(prime.reg == kDmcontrol);
152	  CHECK((prime.value & 1u) == 1u);                  // dmactive
153	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
154	
155	  const auto& halt = bus.ops[1];
156	  CHECK(halt.kind == DmiOp::Kind::Write);
157	  CHECK(halt.reg == kDmcontrol);
158	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
159	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
