592	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
593	          "before the architectural V-CSR restore and counter restore")
594	{
595	  RecordingBus bus;
596	  bus.dmstatus_value = (1u << 9) | (1u << 17);
597	
598	  auto s = rv64_state(0x80001000, 0);
599	  s.flags  |= HYBRID_FLAG_V;
600	  s.vlenb  = 64;
601	  s.vl     = 16;
602	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
603	  s.vstart = 7;
604	
605	  hybrid::ResumeDriver driver(bus);
606	  driver.resume(s);
607	
608	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
609	  std::vector<int> missing;
610	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
611	  for (uint16_t v = 0; v < 32; ++v) {
612	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
613	    std::optional<std::size_t> at;
614	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
615	      const auto& op = bus.ops[i];
616	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
617	          && op.value == want) { at = i; break; }
618	    }
619	    if (!at) { missing.push_back(v); continue; }
620	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
621	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
622	  }
623	  CHECK(missing.empty());
624	  REQUIRE(first_vle_idx.has_value());
625	  REQUIRE(last_vle_idx.has_value());
626	
627	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
628	  //     first and last register.
629	  auto x7_gpa_staged = [&](uint64_t gpa) {
630	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
631	      const auto& op = bus.ops[i];
632	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
633	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
634	          && ((op.value >> 16) & 1u)) {
635	        const auto& d0 = bus.ops[i - 2];
636	        const auto& d1 = bus.ops[i - 1];
637	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
638	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
639	          return true;
640	      }
641	    }
642	    return false;
643	  };
644	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa));
645	  CHECK(x7_gpa_staged(hybrid::kVScratchGpa + 31ull * HYBRID_VLEN_BYTES_MAX));
646	
647	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
648	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
649	  //     (so the vle8.v insns cannot pollute the resumed counters).
650	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
651	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
652	    const auto& op = bus.ops[i];
