787	TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
788	{
789	  // The B9 audit claimed write_csr_abstract_or_pb reads abstractcs without
790	  // first polling busy. In fact write_64bit_register -> write_register_abstract
791	  // calls poll_until_clear(busy) before returning, so by the time the cmderr
792	  // check runs, busy is already clear. This test pins that contract: between
793	  // every kCommand write and the next kAbstractcs read, the recorded ops
794	  // must include at least one kAbstractcs read (the busy poll). If a future
795	  // refactor regresses by removing the chained poll, this test fails.
796	  RecordingBus bus;
797	  bus.dmstatus_value = (1u << 9) | (1u << 17);
798	
799	  hybrid::ResumeDriver driver(bus);
800	  driver.resume(rv64_state(0x80001000, 0xdeadbeef));
801	
802	  // Walk ops; between each kCommand write and the very next kAbstractcs
803	  // read by an unrelated caller, there must be at least one kAbstractcs
804	  // read (the busy poll from write_register_abstract).
805	  bool saw_cmd = false;
806	  std::size_t reads_since_cmd = 0;
807	  bool all_cmds_had_abstractcs_poll = true;
808	  for (const auto& op : bus.ops) {
809	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
810	      if (saw_cmd && reads_since_cmd == 0)
811	        all_cmds_had_abstractcs_poll = false;
812	      saw_cmd = true;
813	      reads_since_cmd = 0;
814	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
815	               && op.reg == kAbstractcs) {
816	      ++reads_since_cmd;
817	    }
818	  }
819	  CHECK(all_cmds_had_abstractcs_poll);
820	  // The final kCommand write must also be followed by an abstractcs read.
821	  CHECK(reads_since_cmd > 0u);
822	}
